import {
  OdometerResponse,
  ProcessImageOptions,
  ConfidenceLevel,
} from './types';
import { OCRProvider } from './ocr.provider';
import {
  CONFIDENCE_THRESHOLDS,
  SUPPORTED_IMAGE_FORMATS,
  ERROR_MESSAGES,
  ERROR_CODES,
} from './constants';

export class OdometerService {
  constructor(private ocrProvider: OCRProvider) {}

  async processImage(options: ProcessImageOptions): Promise<OdometerResponse> {
    const { imageBuffer, filename } = options;

    if (!imageBuffer || imageBuffer.length === 0) {
      return {
        error: ERROR_CODES.MISSING_IMAGE,
        message: ERROR_MESSAGES.MISSING_IMAGE,
      };
    }

    const fileExtension = this.getFileExtension(filename);
    if (!SUPPORTED_IMAGE_FORMATS.includes(fileExtension as any)) {
      return {
        error: ERROR_CODES.UNSUPPORTED_FILE_TYPE,
        message: ERROR_MESSAGES.UNSUPPORTED_FILE_TYPE,
      };
    }

    try {
      const ocrResult = await this.ocrProvider.processImage(imageBuffer);

      if (ocrResult.confidence < CONFIDENCE_THRESHOLDS.REJECT) {
        return {
          error: ERROR_CODES.UNREADABLE_IMAGE,
          message: ERROR_MESSAGES.UNREADABLE_IMAGE,
        };
      }

      const cleanedText = this.extractNumericValue(ocrResult.text);
      if (!cleanedText) {
        return {
          error: ERROR_CODES.UNREADABLE_IMAGE,
          message: ERROR_MESSAGES.UNREADABLE_IMAGE,
        };
      }

      const reading = parseInt(cleanedText, 10);
      if (isNaN(reading)) {
        return {
          error: ERROR_CODES.UNREADABLE_IMAGE,
          message: ERROR_MESSAGES.UNREADABLE_IMAGE,
        };
      }

      const confidence = this.mapConfidenceLevel(ocrResult.confidence);

      return {
        reading,
        unit: 'miles',
        confidence,
      };
    } catch {
      return {
        error: ERROR_CODES.UNREADABLE_IMAGE,
        message: ERROR_MESSAGES.UNREADABLE_IMAGE,
      };
    }
  }

  private getFileExtension(filename: string): string {
    return filename.split('.').pop()?.toLowerCase() || '';
  }

  private extractNumericValue(text: string): string {
    const digits = text.replace(/\D/g, '');
    return digits;
  }

  private mapConfidenceLevel(confidence: number): ConfidenceLevel {
    if (confidence >= CONFIDENCE_THRESHOLDS.HIGH) {
      return 'high';
    } else if (confidence >= CONFIDENCE_THRESHOLDS.MEDIUM) {
      return 'medium';
    } else if (confidence >= CONFIDENCE_THRESHOLDS.LOW) {
      return 'low';
    }
    return 'low';
  }
}

