import request from 'supertest';
import express from 'express';
import { createApp } from '../app';

describe('POST /odometer/reading', () => {
  let app: express.Application;

  beforeEach(() => {
    app = createApp();
  });

  describe('Multipart upload', () => {
    it('should extract reading from JPEG image via multipart', async () => {
      const response = await request(app)
        .post('/odometer/reading')
        .attach('image', Buffer.from('fake-jpeg'), 'odometer.jpg');

      expect(response.status).toBe(200);
      expect(response.body).toHaveProperty('reading');
      expect(response.body).toHaveProperty('unit');
      expect(response.body).toHaveProperty('confidence');
    });

    it('should extract reading from PNG image via multipart', async () => {
      const response = await request(app)
        .post('/odometer/reading')
        .attach('image', Buffer.from('fake-png'), 'odometer.png');

      expect(response.status).toBe(200);
      expect(response.body).toHaveProperty('reading');
    });

    it('should return 400 when no image field provided', async () => {
      const response = await request(app)
        .post('/odometer/reading')
        .field('other_field', 'value');

      expect(response.status).toBe(400);
      expect(response.body.error).toBe('MISSING_IMAGE');
    });

    it('should return 415 for unsupported format via multipart', async () => {
      const response = await request(app)
        .post('/odometer/reading')
        .attach('image', Buffer.from('fake-gif'), 'odometer.gif');

      expect(response.status).toBe(400);
      expect(response.body.error).toBe('UNSUPPORTED_FILE_TYPE');
    });
  });

  describe('Base64 JSON upload', () => {
    it('should extract reading from Base64 encoded image', async () => {
      const base64Image = Buffer.from('fake-image').toString('base64');

      const response = await request(app)
        .post('/odometer/reading')
        .send({
          image: base64Image,
          filename: 'odometer.jpg',
        });

      expect(response.status).toBe(200);
      expect(response.body).toHaveProperty('reading');
      expect(response.body).toHaveProperty('unit');
      expect(response.body).toHaveProperty('confidence');
    });

    it('should return 400 when image field missing in JSON', async () => {
      const response = await request(app)
        .post('/odometer/reading')
        .send({
          filename: 'odometer.jpg',
        });

      expect(response.status).toBe(400);
      expect(response.body.error).toBe('MISSING_IMAGE');
    });

    it('should return 400 when filename missing in JSON', async () => {
      const base64Image = Buffer.from('fake-image').toString('base64');

      const response = await request(app)
        .post('/odometer/reading')
        .send({
          image: base64Image,
        });

      expect(response.status).toBe(400);
      expect(response.body.error).toBe('MISSING_IMAGE');
    });

    it('should return 415 for unsupported format in JSON', async () => {
      const base64Image = Buffer.from('fake-image').toString('base64');

      const response = await request(app)
        .post('/odometer/reading')
        .send({
          image: base64Image,
          filename: 'odometer.gif',
        });

      expect(response.status).toBe(400);
      expect(response.body.error).toBe('UNSUPPORTED_FILE_TYPE');
    });
  });

  describe('Error responses', () => {
    it('should return 400 with UNREADABLE_IMAGE for invalid image', async () => {
      const response = await request(app)
        .post('/odometer/reading')
        .attach('image', Buffer.from('corrupted'), 'odometer.jpg');

      expect(response.status).toBe(400);
      expect(response.body.error).toBe('UNREADABLE_IMAGE');
      expect(response.body.message).toBeDefined();
    });

    it('should return 415 for unsupported file type', async () => {
      const response = await request(app)
        .post('/odometer/reading')
        .attach('image', Buffer.from('fake'), 'odometer.bmp');

      expect(response.status).toBe(400);
      expect(response.body.error).toBe('UNSUPPORTED_FILE_TYPE');
