  path: '/odometer/reading',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(payload)
  }
};

const req = http.request(options, (res) => {
  let data = '';

  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    console.log('\n✅ Happy Path Response:\n');
    console.log('Status:', res.statusCode);
    console.log('Response:', JSON.stringify(JSON.parse(data), null, 2));
    console.log('\n');
  });
});

req.on('error', (e) => {
  console.error('\n❌ Error: Make sure server is running (npm start or npm run dev)\n');
  console.error(e.message);
  process.exit(1);
});

req.write(payload);
req.end();
